package com.aoo.bcg.common.invite;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.Base64;import java.util.Objects;
/** Versioned, expiry-bound HMAC invite token. No join authority is inferred from the token alone. */
public final class SignedInviteService{public record SignedInvite(String payload,String signature){}private final byte[]key;private final AuthoritativeTimeSource time;public SignedInviteService(byte[]key,AuthoritativeTimeSource time){if(key==null||key.length<32)throw new IllegalArgumentException("invite signing key must be at least 256 bits");this.key=key.clone();this.time=Objects.requireNonNull(time);}public SignedInvite sign(InvitePayload value){String canonical=String.join("|",String.valueOf(value.roomId()),String.valueOf(value.gameId()),String.valueOf(value.clubId()),value.inviteId(),value.playVersion(),String.valueOf(value.expiresAt().toEpochMilli()));String payload=Base64.getUrlEncoder().withoutPadding().encodeToString(canonical.getBytes(StandardCharsets.UTF_8));return new SignedInvite(payload,signature(payload));}public InvitePayload verify(SignedInvite token){if(token==null||!MessageDigest.isEqual(signature(token.payload()).getBytes(StandardCharsets.US_ASCII),token.signature().getBytes(StandardCharsets.US_ASCII)))throw new SecurityException("invite signature invalid");String[]parts=new String(Base64.getUrlDecoder().decode(token.payload()),StandardCharsets.UTF_8).split("\\|",-1);if(parts.length!=6)throw new SecurityException("invite payload invalid");var value=new InvitePayload(Long.parseLong(parts[0]),Integer.parseInt(parts[1]),Long.parseLong(parts[2]),parts[3],parts[4],java.time.Instant.ofEpochMilli(Long.parseLong(parts[5])));if(!time.now().isBefore(value.expiresAt()))throw new SecurityException("invite expired");return value;}private String signature(String payload){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));}catch(java.security.GeneralSecurityException impossible){throw new IllegalStateException(impossible);}}}
